contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint firstVal, uint secondVal) public {
        // fresh c: not yet initialized
        c.SetMinSum(firstVal); if (__ESBMC_reverted()) return;
        uint mid = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(secondVal); if (__ESBMC_reverted()) return;
        uint last = c.MinSum(); if (__ESBMC_reverted()) return;
        // MinSum always tracks the latest value while uninitialized
        assert(mid == firstVal && last == secondVal);
    }
}

