// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 firstVal, uint256 secondVal) internal {
        try c.SetMinSum(firstVal) {} catch { return; }
        uint256 mid;
        try c.MinSum() returns (uint256 __r) { mid = __r; } catch { return; }
        try c.SetMinSum(secondVal) {} catch { return; }
        uint256 last;
        try c.MinSum() returns (uint256 __r) { last = __r; } catch { return; }
        assertTrue(mid == firstVal && last == secondVal);
    }

    function testFuzz_run(uint256 firstVal, uint256 secondVal) public {
        _run(firstVal, secondVal);
    }

    receive() external payable {}
}
